      "achados": [
        {
          "proposicao": "A fonte aparenta tratar de automação industrial, gerenciamento de alarmes, normas de gestão de alarmes e estudo de caso em produção offshore, mas os trechos fornecidos são majoritariamente sumário e legendas.",
          "trechos": [
            "E4a3d2b370af567a3:0:698",
