        {
          "proposicao": "A fonte relata seleção de equipamentos classificados como sistemas complexos de partida e parada com interface homem-máquina para estudo ergonômico e de confiabilidade em refinaria.",
          "trechos": [
            "E756f473dab4a4fde:694:1387",
            "E756f473dab4a4fde:1387:2086"
          ],
          "condicoes": [
